        max-width: 800px;
        margin: 20px auto;
        background: #ffffff;
        padding: 30px;
        border-radius: 10px;
        box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    }

    h1 {
        color: #1a4e8a;
        font-size: 22px;
    }

    h2 {
        color: #2b2b2b;
        font-size: 18px;
