        border-left: 4px solid #1a4e8a;
        margin: 15px 0;
    }

    ul {
        margin: 10px 0 10px 20px;
        font-size: 14px;
        color: #333;
    }

    .footer {
        margin-top: 30px;
        font-size: 13px;
        color: #555;
        border-top: 1px solid #ddd;
        padding-top: 15px;
    }

